def run(ready_at=None, stop_at=None):
    state = 'waiting'
    frames = 0
    for tick in range(8):
        if state == 'waiting':
            if tick == ready_at:
                state = 'running'
            elif tick >= 3:
                return 'startup timeout'
        if state == 'running':
            frames += 1
            if tick == stop_at:
                return f'stopped after {frames} frames'
    return f'{state}, {frames} frames'

ready_and_stop = run(ready_at=1, stop_at=4)
never_ready = run()
keeps_running = run(ready_at=1)
assert ready_and_stop == 'stopped after 4 frames'
assert never_ready == 'startup timeout'
assert keeps_running == 'running, 7 frames'
print('ready + stop:', ready_and_stop)
print('no readiness:', never_ready)
print('no stop request:', keeps_running)
